import React from "react";

// S-capsule logo mark: top pill (white/black), diagonal parallelogram (light grey),
// bottom pill (black/orange).
export default function Logo({ size = 36, className = "" }) {
    const displayHeight = size === 28 ? 32 : size;
    return (
        <div className={`flex items-center ${className}`} data-testid="brand-logo">
            <img 
                src="/logo_dark.png" 
                alt="Studio Form Logo" 
                className="w-auto object-contain block"
                style={{ height: displayHeight }}
            />
        </div>
    );
}
